import java.util.ArrayList;
import java.util.Comparator;
import java.util.Objects;
import java.util.PriorityQueue;

public final class HuffmanCoding {

    private HuffmanCoding() {
        // Utility class.
    }

    private static final class Node {
        final int weight;
        final int sequence;
        final Node left;
        final Node right;

        Node(int weight, int sequence) {
            this.weight = weight;
            this.sequence = sequence;
            this.left = null;
            this.right = null;
        }

        Node(Node left, Node right) {
            this.weight = left.weight + right.weight;
            this.sequence = Math.min(left.sequence, right.sequence);
            this.left = left;
            this.right = right;
        }

        boolean isLeaf() {
            return left == null && right == null;
        }
    }

    private static final Comparator<Node> NODE_ORDER = Comparator
            .comparingInt((Node node) -> node.weight)
            .thenComparingInt(node -> node.sequence);

    /**
     * Builds Huffman codes for the provided frequencies.
     *
     * <p>The returned list follows the tree traversal order used by the original
     * implementation, which matches the expected ordering for the existing API.
     * The {@code symbols} argument is validated only for length compatibility.
     */
    public static ArrayList<String> huffmanCodes(String symbols, int[] frequencies) {
        Objects.requireNonNull(symbols, "symbols must not be null");
        Objects.requireNonNull(frequencies, "frequencies must not be null");

        if (symbols.length() != frequencies.length) {
            throw new IllegalArgumentException("symbols and frequencies must have the same length");
        }

        return buildHuffmanCodes(frequencies);
    }

    private static ArrayList<String> buildHuffmanCodes(int[] frequencies) {
        if (frequencies.length == 0) {
            return new ArrayList<>();
        }

        validateFrequencies(frequencies);
        HuffmanTree tree = HuffmanTree.fromFrequencies(frequencies);
        return tree.codesInTraversalOrder(frequencies.length);
    }

    private static void validateFrequencies(int[] frequencies) {
        for (int frequency : frequencies) {
            if (frequency < 0) {
                throw new IllegalArgumentException("frequencies must be non-negative");
            }
        }
    }

    private static final class HuffmanTree {
        private final Node root;

        private HuffmanTree(Node root) {
            this.root = root;
        }

        static HuffmanTree fromFrequencies(int[] frequencies) {
            PriorityQueue<Node> queue = new PriorityQueue<>(NODE_ORDER);
            for (int i = 0; i < frequencies.length; i++) {
                queue.add(new Node(frequencies[i], i));
            }

            while (queue.size() > 1) {
                Node left = queue.poll();
                Node right = queue.poll();
                queue.add(new Node(left, right));
            }

            return new HuffmanTree(queue.peek());
        }

        ArrayList<String> codesInTraversalOrder(int expectedSize) {
            ArrayList<String> codes = new ArrayList<>(expectedSize);
            fillCodes(root, new StringBuilder(), codes);
            return codes;
        }

        private void fillCodes(Node node, StringBuilder prefix, ArrayList<String> codes) {
            if (node == null) {
                return;
            }

            if (node.isLeaf()) {
                codes.add(prefix.length() == 0 ? "0" : prefix.toString());
                return;
            }

            prefix.append('0');
            fillCodes(node.left, prefix, codes);
            prefix.setLength(prefix.length() - 1);

            prefix.append('1');
            fillCodes(node.right, prefix, codes);
            prefix.setLength(prefix.length() - 1);
        }
    }
}

import java.util.ArrayList;

public final class HuffmanCodingTest {

    private HuffmanCodingTest() {
    }

    public static void main(String[] args) {
        shouldMatchSampleOutput();
        shouldHandleSingleSymbol();
        shouldHandleEmptyInput();
        shouldStabilizeEqualFrequencies();
        shouldRejectMismatchedLengths();
        shouldRejectNegativeFrequencies();
        System.out.println("All HuffmanCoding tests passed.");
    }

    private static void shouldMatchSampleOutput() {
        assertCodes(
                HuffmanCoding.huffmanCodes("abcdef", new int[] {5, 9, 12, 13, 16, 45}),
                "0", "100", "101", "1100", "1101", "111");
    }

    private static void shouldHandleSingleSymbol() {
        assertCodes(HuffmanCoding.huffmanCodes("a", new int[] {42}), "0");
    }

    private static void shouldHandleEmptyInput() {
        assertCodes(HuffmanCoding.huffmanCodes("", new int[0]));
    }

    private static void shouldStabilizeEqualFrequencies() {
        assertCodes(HuffmanCoding.huffmanCodes("abcd", new int[] {1, 1, 1, 1}),
                "00", "01", "10", "11");
    }

    private static void shouldRejectMismatchedLengths() {
        expectThrows(IllegalArgumentException.class,
                () -> HuffmanCoding.huffmanCodes("ab", new int[] {1}),
                "mismatched lengths");
    }

    private static void shouldRejectNegativeFrequencies() {
        expectThrows(IllegalArgumentException.class,
                () -> HuffmanCoding.huffmanCodes("ab", new int[] {1, -1}),
                "negative frequencies");
    }

    private static void assertEquals(Object expected, Object actual, String label) {
        if (!expected.equals(actual)) {
            throw new AssertionError(label + ": expected " + expected + " but was " + actual);
        }
    }

    private static void assertCodes(ArrayList<String> actual, String... expected) {
        assertEquals(expected.length, actual.size(), "code count");
        for (int i = 0; i < expected.length; i++) {
            assertEquals(expected[i], actual.get(i), "code at index " + i);
        }
    }

    private static void expectThrows(Class<? extends Throwable> type, ThrowingRunnable action, String label) {
        try {
            action.run();
        } catch (Throwable throwable) {
            if (type.isInstance(throwable)) {
                return;
            }
            throw new AssertionError(label + ": expected " + type.getSimpleName()
                    + " but got " + throwable.getClass().getSimpleName(), throwable);
        }

        throw new AssertionError(label + ": expected " + type.getSimpleName() + " but nothing was thrown");
    }

    @FunctionalInterface
    private interface ThrowingRunnable {
        void run();
    }
}

